import "fmt"

// usageError wraps an error to signal that it should map to exit code 2.
// Use this for invalid arguments, missing flags, and other caller mistakes.
type usageError struct {
	err error
}

func (e *usageError) Error() string {
	return e.err.Error()
}

func (e *usageError) Unwrap() error {
	return e.err
}

// newUsageErrorf creates a usageError with formatted text.
func newUsageErrorf(format string, args ...any) error {
	return &usageError{err: fmt.Errorf(format, args...)}
}

package main

import (
	"context"
	"errors"
	"os"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

func main() {
	if err := Execute(); err != nil {
		os.Exit(exitCode(err))
	}
}

// exitCode maps errors to Unix-style exit codes.
//
//	0   — success
//	1   — runtime error
//	2   — usage error (invalid flags, arguments, or missing required input)
//	127 — a required external binary is missing from PATH
//	130 — interrupted (SIGINT)
func exitCode(err error) int {
	if err == nil {
		return 0
	}
	var ue *usageError
	if errors.As(err, &ue) {
		return 2
	}
	// Cobra's built-in flag/argument errors don't wrap a typed error,
	// so we fall back to message prefix detection for those.
	if isCobraUsageError(err) {
		return 2
	}
	// A missing dependency is "command not found", not a generic failure —
	// scripts and CI can tell the two apart and react differently.
	if errors.Is(err, command.ErrNotInstalled) {
		return 127
	}
	// Ctrl-C during a long operation (the ArgoCD wait, a push over SSH) must
	// look like a signal, not a failure of the thing being run.
	if errors.Is(err, context.Canceled) {
		return 130
	}
	return 1
}

// isCobraUsageError detects Cobra-generated flag and argument errors
// that should map to exit code 2. These are errors from Cobra itself,
// not from our RunE functions (which should use usageError).
func isCobraUsageError(err error) bool {
	msg := err.Error()
	prefixes := []string{
		"unknown command",
		"unknown flag",
		"invalid argument",
		"accepts ",
		"requires ",
		"required flag(s)",
		"at least one of the flags",
	}
	for _, p := range prefixes {
		if strings.HasPrefix(msg, p) {
			return true
		}
	}
	return false
}

package main

import (
	"errors"
	"testing"
)

func TestResolveCreateName(t *testing.T) {
	t.Run("name only defaults output and sets name", func(t *testing.T) {
		sets := map[string]any{}
		out, err := resolveCreateName("orders", "", sets)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if out != "orders" {
			t.Errorf("output = %q, want %q", out, "orders")
		}
		if sets["name"] != "orders" {
			t.Errorf("sets[name] = %v, want %q", sets["name"], "orders")
		}
	})

	t.Run("explicit output is kept, name still set", func(t *testing.T) {
		// Mirrors `dotnet new`: -o is the literal output location; -n never
		// nests a subdirectory under it.
		sets := map[string]any{}
		out, err := resolveCreateName("orders", "./elsewhere", sets)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if out != "./elsewhere" {
			t.Errorf("output = %q, want %q", out, "./elsewhere")
		}
		if sets["name"] != "orders" {
			t.Errorf("sets[name] = %v, want %q", sets["name"], "orders")
		}
	})

	t.Run("name plus --set name conflict is a usage error", func(t *testing.T) {
		sets := map[string]any{"name": "bar"}
		_, err := resolveCreateName("foo", "", sets)
		if err == nil {
			t.Fatal("expected error, got nil")
		}
		var ue *usageError
		if !errors.As(err, &ue) {
			t.Errorf("error %v is not a usageError", err)
		}
		if sets["name"] != "bar" {
			t.Errorf("sets[name] mutated on conflict: %v", sets["name"])
		}
	})

	t.Run("no name is a passthrough", func(t *testing.T) {
		sets := map[string]any{}
		out, err := resolveCreateName("", "./out", sets)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if out != "./out" {
